def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for br in range(0, h, 3):
        row = []
        for bc in range(0, w, 3):
            counts = Counter(
                grid[r][c]
                for r in range(br, min(br + 3, h))
                for c in range(bc, min(bc + 3, w))
                if grid[r][c] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
